WITH valid AS (SELECT id, order_id, shipped_date, cost, status, DATEDIFF(delivered_date, shipped_date) / 7 AS weeks_shipped_date_to_delivered_date, CEIL(cost) AS cost_whole, COALESCE(carrier, 'DIRECT') AS resolved_carrier FROM shipments WHERE shipped_date > TO_DATE('2023-04-29') AND carrier IS DISTINCT FROM 'Kerry') SELECT id, order_id, weeks_shipped_date_to_delivered_date, cost_whole, resolved_carrier, ROW_NUMBER() OVER (ORDER BY weeks_shipped_date_to_delivered_date, id) AS event_seq, NTILE(10) OVER (PARTITION BY YEAR(shipped_date), status ORDER BY cost, id) AS cost_bucket, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY cost, id) AS seq_no FROM valid WHERE status = 'RETURNED';
